import java.text.SimpleDateFormat;
import java.util.*;
import java.util.ArrayList;
import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TimeZone;
import org.apache.commons.lang.Validate;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;

public class FastDateFormat_getDateTimeInstance_TriageGen1Test {

    @Test
    public void testGetDateTimeInstance_Basic() {
        int dateStyle = Calendar.MEDIUM;
        int timeStyle = Calendar.SHORT;
        TimeZone tz = TimeZone.getTimeZone("UTC");
        Locale locale = Locale.US;

        FastDateFormat format1 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz, locale);
        assertNotNull("Format should not be null", format1);
        assertEquals("TimeZone should match", tz, format1.getTimeZone());
        assertEquals("Locale should match", locale, format1.getLocale());

        // Test cache hit: same parameters should return the same instance
        FastDateFormat format2 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz, locale);
        assertEquals("Should return cached instance", format1, format2);
    }

    @Test
    public void testGetDateTimeInstance_NullTimeZone() {
        int dateStyle = Calendar.FULL;
        int timeStyle = Calendar.FULL;
        TimeZone tz = null;
        Locale locale = Locale.FRANCE;

        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz, locale);
        assertNotNull("Format should not be null even with null TimeZone", format);
        assertEquals("Locale should match", locale, format.getLocale());
    }

    @Test
    public void testGetDateTimeInstance_DifferentLocales() {
        int dateStyle = Calendar.SHORT;
        int timeStyle = Calendar.SHORT;
        TimeZone tz = TimeZone.getDefault();

        FastDateFormat formatUS = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz, Locale.US);
        FastDateFormat formatUK = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz, Locale.UK);

        assertNotNull(formatUS);
        assertNotNull(formatUK);
        // They should be different instances because Locale is part of the key
        assertNotSame("Different locales should produce different instances", formatUS, formatUK);
    }

    @Test
    public void testGetDateTimeInstance_DifferentTimeZones() {
        int dateStyle = Calendar.SHORT;
        int timeStyle = Calendar.SHORT;
        Locale locale = Locale.US;

        TimeZone tz1 = TimeZone.getTimeZone("GMT");
        TimeZone tz2 = TimeZone.getTimeZone("America/New_York");

        FastDateFormat format1 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz1, locale);
        FastDateFormat format2 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz2, locale);

        assertNotNull(format1);
        assertNotNull(format2);
        assertNotSame("Different timezones should produce different instances", format1, format2);
    }

    @Test
    public void testGetDateTimeInstance_DifferentStyles() {
        int dateStyle1 = Calendar.SHORT;
        int timeStyle1 = Calendar.SHORT;
        int dateStyle2 = Calendar.LONG;
        int timeStyle2 = Calendar.LONG;
        TimeZone tz = TimeZone.getDefault();
        Locale locale = Locale.US;

        FastDateFormat format1 = FastDateFormat.getDateTimeInstance(dateStyle1, timeStyle1, tz, locale);
        FastDateFormat format2 = FastDateFormat.getDateTimeInstance(dateStyle2, timeStyle2, tz, locale);

        assertNotNull(format1);
        assertNotNull(format2);
        // Patterns will differ, so instances should be different
        assertNotSame("Different styles should produce different instances", format1, format2);
    }

    @Test
    public void testGetDateTimeInstance_FormattingFunctionality() {
        // Verify that the returned object actually works
        int dateStyle = Calendar.MEDIUM;
        int timeStyle = Calendar.MEDIUM;
        TimeZone tz = TimeZone.getTimeZone("UTC");
        Locale locale = Locale.US;

        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz, locale);
        long now = System.currentTimeMillis();
        String formatted = format.format(now);

        assertNotNull(formatted);
        // Check if the format string is not empty
        assert(formatted.length() > 0);
    }
}
